    'june': 6, 'july': 7, 'august': 8, 'september': 9,
    'october': 10, 'november': 11, 'december': 12,
}

PRIORITY_PATTERNS = [
    (1, [r'GRAND\s+TOTAL']),
    (2, [r'TOTAL\s*:?\s*RM']),
    (3, [r'TOTAL\s+AMOUNT']),
    (4, [r'TOTAL\s+DUE', r'AMOUNT\s+DUE', r'BALANCE\s+DUE',
         r'NETT?\s+TOTAL', r'\bTOTAL\b', r'\bAMOUNT\b']),
]

EXCLUSION_PATTERNS = [
    r'SUB\s*TOTAL', r'TAX', r'GST', r'SST', r'DISCOUNT',
    r'CHANGE', r'CASH\s+TENDERED',
]


def ocr_image(path):
    img = Image.open(path)
    gray = ImageOps.grayscale(img)
    gray = ImageOps.autocontrast(gray)
    text = pytesseract.image_to_string(gray)
    return text


def extract_date(text):
    candidates = []

    # DD/MM/YYYY or DD-MM-YYYY (4-digit year)
    for m in re.finditer(r'\b(\d{1,2})[/\-\.](\d{1,2})[/\-\.](\d{4})\b', text):
        d, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
        if 1 <= d <= 31 and 1 <= mo <= 12 and 2000 <= y <= 2099:
            candidates.append((m.start(), f"{y:04d}-{mo:02d}-{d:02d}"))

    # DD/MM/YY (2-digit year)
    for m in re.finditer(r'\b(\d{1,2})[/\-\.](\d{1,2})[/\-\.](\d{2})\b', text):
        d, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
        if 1 <= d <= 31 and 1 <= mo <= 12:
            y_full = 2000 + y
            candidates.append((m.start(), f"{y_full:04d}-{mo:02d}-{d:02d}"))

    # DD Mon YYYY or DD Mon YY
    for m in re.finditer(
        r'\b(\d{1,2})\s+(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*\s+(\d{2,4})\b',
        text, re.IGNORECASE
    ):
        d = int(m.group(1))
        mo = MONTH_MAP[m.group(2).lower()]
        y = int(m.group(3))
        if y < 100:
            y += 2000
        if 1 <= d <= 31 and 2000 <= y <= 2099:
            candidates.append((m.start(), f"{y:04d}-{mo:02d}-{d:02d}"))

    if candidates:
        candidates.sort(key=lambda x: x[0])
        return candidates[0][1]
    return None


def find_amount_in_line(line):
    """Find a numeric amount (with comma separators) in the line.
    Returns the LAST such number as a string."""
    nums = re.findall(r'(?<![\d.])(\d{1,3}(?:,\d{3})+(?:\.\d{1,2})?|\d+\.\d{1,2})(?![\d])', line)
    if nums:
        return nums[-1]
    return None


def find_last_number(line):
    nums = re.findall(r'(?<![\d.])(\d{1,3}(?:,\d{3})+(?:\.\d{1,2})?|\d+\.\d{1,2})(?![\d])', line)
    if nums:
        return nums[-1]
    return None


def normalize_amount(s):
    try:
        v = float(s.replace(',', ''))
        return f"{v:.2f}"
    except (ValueError, TypeError):
        return None


def line_priority(upper_line):
    for prio, patterns in PRIORITY_PATTERNS:
        for p in patterns:
            if re.search(p, upper_line):
                return prio
    return None


def is_excluded(upper_line):
    return any(re.search(p, upper_line) for p in EXCLUSION_PATTERNS)


def extract_total(text):
    lines = text.splitlines()
    best = None  # (priority, line_idx, amount_string)

    for i, line in enumerate(lines):
        upper = line.upper()
        if is_excluded(upper):
            continue
        prio = line_priority(upper)
        if prio is None:
            continue

        amount = find_amount_in_line(line)
        if amount is None and i + 1 < len(lines):
            next_line = lines[i + 1]
            if not is_excluded(next_line.upper()):
                amount = find_last_number(next_line)

        if amount is None:
            continue

        if (best is None
                or prio < best[0]
                or (prio == best[0] and i > best[1])):
            best = (prio, i, amount)

    if best:
        return normalize_amount(best[2])
    return None


def process_image(path):
    text = ocr_image(path)
    date = extract_date(text)
    total = extract_total(text)
    return date, total, text


def main():
    files = sorted(f for f in os.listdir(IMG_DIR) if f.lower().endswith('.jpg'))

    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = 'results'
    ws.append(['filename', 'date', 'total_amount'])

    for fname in files:
        path = os.path.join(IMG_DIR, fname)
        date, total, _ = process_image(path)
        ws.append([fname, date, total])
        print(f"{fname}: date={date}, total={total}")

    wb.save(OUT_FILE)
    print(f"Saved to {OUT_FILE}")


if __name__ == '__main__':
    main()
