import os
import re
import pytesseract
from PIL import Image
import openpyxl

IMG_DIR = '/app/workspace/dataset/img'
OUT_FILE = '/app/workspace/stat_ocr.xlsx'

MONTH_MAP = {
    'jan': 1, 'feb': 2, 'mar': 3, 'apr': 4, 'may': 5, 'jun': 6,
    'jul': 7, 'aug': 8, 'sep': 9, 'oct': 10, 'nov': 11, 'dec': 12,
    'january': 1, 'february': 2, 'march': 3, 'april': 4,
    'june': 6, 'july': 7, 'august': 8, 'september': 9,
    'october': 10, 'november': 11, 'december': 12,
}

PRIORITY_PATTERNS = [
    (1, [re.compile(r'\bGRAND\s+TOTAL\b', re.I)]),
    (2, [re.compile(r'\bTOTAL\s*:?\s*RM\b', re.I)]),
    (3, [re.compile(r'\bTOTAL\s+AMOUNT\b', re.I)]),
    (4, [
        re.compile(r'\bNETT?\s+TOTAL\b', re.I),
        re.compile(r'\bTOTAL\s+DUE\b', re.I),
        re.compile(r'\bAMOUNT\s+DUE\b', re.I),
        re.compile(r'\bBALANCE\s+DUE\b', re.I),
        re.compile(r'\bTOTAL\b', re.I),
        re.compile(r'\bAMOUNT\b', re.I),
    ]),
]

EXCLUSION_PATTERNS = [
    re.compile(r'\bSUB\s*-?\s*TOTAL\b', re.I),
    re.compile(r'\bTOTAL\s*(TAX|GST|SST)\b', re.I),
    re.compile(r'\bDISCOUNT\b', re.I),
    re.compile(r'\bCHANGE\b', re.I),
    re.compile(r'\bCASH\s+TENDERED\b', re.I),
]

GST_SUMMARY_PATTERN = re.compile(r'GST\s*SUMMARY|TAX\s*SUMMARY', re.I)

AMOUNT_RE = re.compile(
    r'(?<![\d.])(\d{1,3}(?:,\d{3})+(?:\.\d{1,2})?|\d+\.\d{1,2})(?![\d])'
)


def ocr_text(path):
    img = Image.open(path)
    return pytesseract.image_to_string(img)


def extract_date(text):
    candidates = []

    for m in re.finditer(r'\b(\d{1,2})[/\-\.](\d{1,2})[/\-\.](\d{4})\b', text):
        d, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
        if 1 <= d <= 31 and 1 <= mo <= 12 and 2000 <= y <= 2099:
            candidates.append((m.start(), f"{y:04d}-{mo:02d}-{d:02d}"))

    for m in re.finditer(r'\b(\d{1,2})[/\-\.](\d{1,2})[/\-\.](\d{2})\b', text):
        d, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
        if 1 <= d <= 31 and 1 <= mo <= 12:
            y_full = 2000 + y
            candidates.append((m.start(), f"{y_full:04d}-{mo:02d}-{d:02d}"))

    for m in re.finditer(
        r'\b(\d{1,2})\s+(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*\s+(\d{2,4})\b',
        text, re.IGNORECASE
    ):
        d = int(m.group(1))
        mo = MONTH_MAP[m.group(2).lower()]
        y = int(m.group(3))
        if y < 100:
            y += 2000
        if 1 <= d <= 31 and 2000 <= y <= 2099:
            candidates.append((m.start(), f"{y:04d}-{mo:02d}-{d:02d}"))

    if candidates:
        candidates.sort(key=lambda x: x[0])
        return candidates[0][1]
    return None


def find_amounts(line):
    return AMOUNT_RE.findall(line)


def normalize_amount(s):
    try:
        v = float(s.replace(',', ''))
        return f"{v:.2f}"
    except (ValueError, TypeError):
        return None


def line_priority(line):
    for prio, patterns in PRIORITY_PATTERNS:
        for p in patterns:
            if p.search(line):
                return prio
    return None


def is_excluded(line):
    return any(p.search(line) for p in EXCLUSION_PATTERNS)


def extract_total(text):
    lines = text.splitlines()

    # Find GST SUMMARY cutoff
    cutoff = len(lines)
    for i, line in enumerate(lines):
        if GST_SUMMARY_PATTERN.search(line):
            cutoff = i
            break

    best = None  # (priority, line_idx, amount_string)

    for i in range(cutoff):
        line = lines[i]
        if is_excluded(line):
            continue
        prio = line_priority(line)
        if prio is None:
            continue

        amounts = find_amounts(line)
        amount = None
        if amounts:
            amount = amounts[-1]
        elif i + 1 < cutoff:
            next_line = lines[i + 1]
            if not is_excluded(next_line):
                next_amounts = find_amounts(next_line)
                if next_amounts:
                    amount = next_amounts[-1]

        if amount is None:
            continue

        if (best is None
                or prio < best[0]
                or (prio == best[0] and i > best[1])):
            best = (prio, i, amount)

    if best:
        return normalize_amount(best[2])
    return None


def process_image(path):
    text = ocr_text(path)
    date = extract_date(text)
    total = extract_total(text)
    return date, total


def main():
    files = sorted(f for f in os.listdir(IMG_DIR) if f.lower().endswith('.jpg'))

    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = 'results'
    ws.append(['filename', 'date', 'total_amount'])

    for fname in files:
        path = os.path.join(IMG_DIR, fname)
        date, total = process_image(path)
        ws.append([fname, date, total])
        print(f"{fname}: date={date}, total={total}")

    wb.save(OUT_FILE)
    print(f"Saved to {OUT_FILE}")


if __name__ == '__main__':
    main()
"}

