    return None


def find_amounts(line):
    return AMOUNT_RE.findall(line)


def normalize_amount(s):
    try:
        v = float(s.replace(',', ''))
        return f"{v:.2f}"
    except (ValueError, TypeError):
        return None


def line_priority(line):
    for prio, patterns in PRIORITY_PATTERNS:
        for p in patterns:
            if p.search(line):
                return prio
    return None


def is_excluded(line):
    return any(p.search(line) for p in EXCLUSION_PATTERNS)


def extract_total(text):
    lines = text.splitlines()

    # Find GST SUMMARY cutoff
    cutoff = len(lines)
    for i, line in enumerate(lines):
        if GST_SUMMARY_PATTERN.search(line):
            cutoff = i
            break

    best = None  # (priority, line_idx, amount_string)

    for i in range(cutoff):
        line = lines[i]
        if is_excluded(line):
            continue
        prio = line_priority(line)
        if prio is None:
